export class TTLCache<T> {
  readonly entries = new Map<string, { value: T; expires: number }>();
  readonly capacity: number;
  constructor(capacity = 64) { this.capacity = capacity; }

  put(key: string, value: T, options: { now: number; ttl: number }): void {
    if (this.capacity < 1 || options.ttl <= 0) return;
    this.entries.delete(key);
    this.entries.set(key, { value, expires: options.now + options.ttl });
    if (this.entries.size > this.capacity) {
      for (const [cachedKey, entry] of this.entries) {
        if (options.now > entry.expires) this.entries.delete(cachedKey);
      }
    }
    while (this.entries.size > this.capacity) {
      this.entries.delete(this.entries.keys().next().value!);
    }
  }

  get(key: string, options: { now: number }): T | undefined {
    const entry = this.entries.get(key);
    if (!entry) return undefined;
    if (options.now > entry.expires) {
      this.entries.delete(key);
      return undefined;
    }
    // Map iteration order tracks recency; retain the original expiration.
    this.entries.delete(key);
    this.entries.set(key, entry);
    return entry.value;
  }
}

import test from "node:test";
import assert from "node:assert/strict";
import { TTLCache } from "../src/cache.ts";

test("successful reads refresh recency without extending TTL", () => {
  const cache = new TTLCache(2);
  cache.put("a", "A", { now: 0, ttl: 10 });
  cache.put("b", "B", { now: 0, ttl: 100 });
  assert.equal(cache.get("a", { now: 5 }), "A");
  cache.put("c", "C", { now: 6, ttl: 100 });
  assert.equal(cache.get("b", { now: 6 }), undefined);
  assert.equal(cache.get("a", { now: 10 }), "A");
  assert.equal(cache.get("a", { now: 11 }), undefined);
  assert.equal(cache.get("c", { now: 11 }), "C");
});

test("updates refresh recency and missing reads leave eviction order intact", () => {
  const cache = new TTLCache(2);
  cache.put("a", 1, { now: 0, ttl: 10 });
  cache.put("b", 2, { now: 0, ttl: 10 });
  cache.put("a", 3, { now: 1, ttl: 20 });
  assert.equal(cache.get("missing", { now: 2 }), undefined);
  assert.equal(cache.entries.size, 2);
  cache.put("c", 4, { now: 2, ttl: 10 });
  assert.equal(cache.get("b", { now: 2 }), undefined);
  assert.equal(cache.get("a", { now: 11 }), 3);
  assert.equal(cache.entries.size, 2);
});

test("expired entries are reclaimed before evicting live keys", () => {
  const cache = new TTLCache(2);
  cache.put("live", 1, { now: 0, ttl: 100 });
  cache.put("expired", 2, { now: 0, ttl: 1 });
  cache.put("new", 3, { now: 2, ttl: 100 });
  assert.equal(cache.get("live", { now: 2 }), 1);
  assert.equal(cache.get("expired", { now: 2 }), undefined);
  assert.equal(cache.get("new", { now: 2 }), 3);
  assert.equal(cache.entries.size, 2);
});

test("expired reads only remove the expired key and capacity stays bounded", () => {
  const cache = new TTLCache(1);
  cache.put("expired", 0, { now: 0, ttl: 1 });
  assert.equal(cache.get("expired", { now: 2 }), undefined);
  for (let i = 0; i < 10; i++) {
    cache.put(String(i), i, { now: 2, ttl: 10 });
    assert.equal(cache.entries.size, 1);
    assert.equal(cache.get(String(i), { now: 2 }), i);
  }
  const disabled = new TTLCache(0);
  disabled.put("a", 1, { now: 0, ttl: 10 });
  assert.equal(disabled.entries.size, 0);
  cache.put("ignored", 1, { now: 2, ttl: 0 });
  assert.equal(cache.get("9", { now: 2 }), 9);
});

